CREATE OR REPLACE FUNCTION public.admin_direct_submit(request_payloads jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_admin_id UUID := auth.uid();
    payload JSONB;
    new_req_id UUID;
    target_id BIGINT;
    act_type TEXT;
    prop_data JSONB;
    orig_data JSONB;
    safe_pin INTEGER;
BEGIN
    -- Verify the caller is truly an Admin
    IF v_admin_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.admins WHERE id = v_admin_id
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Admin privileges required.';
    END IF;

    FOR payload IN SELECT * FROM jsonb_array_elements(request_payloads)
    LOOP
        act_type := payload->>'action_type';
        prop_data := payload->'proposed_data';
        orig_data := payload->'original_data';

        IF (payload->>'post_office_id') IS NOT NULL AND (payload->>'post_office_id') <> '' THEN
            target_id := (payload->>'post_office_id')::BIGINT;
        ELSE
            target_id := NULL;
        END IF;

        IF NULLIF(TRIM(COALESCE(prop_data->>'Pin', '')), '') ~ '^\d+$' THEN
            safe_pin := TRIM(prop_data->>'Pin')::INTEGER;
        ELSE
            safe_pin := NULL;
        END IF;

        -- 1. Record as APPROVED in edit_requests
        INSERT INTO public.edit_requests (
            post_office_id, action_type, proposed_data, original_data, requested_by, status, last_approved_by
        ) VALUES (
            target_id, act_type, prop_data, orig_data, v_admin_id, 'APPROVED', v_admin_id
        ) RETURNING id INTO new_req_id;

        -- 2. Record admin approval vote
        INSERT INTO public.request_approvals (
            request_id, approved_by, is_admin
        ) VALUES (
            new_req_id, v_admin_id, TRUE
        );

        -- 3. Update post_offices (log_post_office_history trigger logs history automatically once)
        IF act_type = 'ADD' THEN
            INSERT INTO public.post_offices (
                "Address", "Office", "Pin", user_id, last_modified_by, last_approved_by, upload_method, is_deleted
            ) VALUES (
                prop_data->>'Address',
                prop_data->>'Office',
                safe_pin,
                v_admin_id,
                v_admin_id,
                v_admin_id,
                'manual',
                FALSE
            ) RETURNING id INTO target_id;

            UPDATE public.edit_requests SET post_office_id = target_id WHERE id = new_req_id;

        ELSIF act_type = 'EDIT' THEN
            UPDATE public.post_offices
            SET "Address" = prop_data->>'Address',
                "Office" = prop_data->>'Office',
                "Pin" = safe_pin,
                last_modified_by = v_admin_id,
                last_approved_by = v_admin_id
            WHERE id = target_id;

        ELSIF act_type = 'DELETE' THEN
            UPDATE public.post_offices
            SET is_deleted = TRUE,
                last_modified_by = v_admin_id,
                last_approved_by = v_admin_id
            WHERE id = target_id;
        END IF;
    END LOOP;

    RETURN 'SUCCESS';
END;
$function$

CREATE OR REPLACE FUNCTION public.check_self_vote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_requested_by uuid;
  v_is_admin boolean;
BEGIN
  SELECT requested_by INTO v_requested_by
  FROM public.edit_requests
  WHERE id = NEW.request_id;

  SELECT EXISTS (
    SELECT 1 FROM public.admins WHERE id = NEW.approved_by
  ) INTO v_is_admin;

  -- Only block non-admins from voting on their own requests
  IF v_requested_by = NEW.approved_by AND NOT v_is_admin THEN
    RAISE EXCEPTION 'You cannot vote on your own request.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.format_title_case()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW."Address" IS NOT NULL THEN
        NEW."Address" := smart_capitalize(NEW."Address");
    END IF;

    IF NEW."Office" IS NOT NULL THEN
        NEW."Office" := smart_capitalize(NEW."Office");
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.postal_phonetic_key(addr text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  s TEXT;
BEGIN
  IF addr IS NULL THEN
    RETURN '';
  END IF;

  -- 1. Lowercase, remove dots, and strip standalone BO/SO/HO/PO/Village tags
  s := LOWER(REPLACE(addr, '.', ''));
  s := REGEXP_REPLACE(s, '\m(bo|so|ho|po|village|vill|gram)\M', '', 'gi');

  -- 2. Normalize common suffix spellings (Kalan/Kalna -> Kala, Gawn/Gawan/Ganw -> Gaon)
  s := REGEXP_REPLACE(s, '\m(kalan|kalna)\M', 'kala', 'gi');
  s := REGEXP_REPLACE(s, '(gawn|gawan|ganw|gaon)\M', 'gaon', 'gi');

  -- 3. Remove all spaces, hyphens, and non-alphanumeric characters
  s := REGEXP_REPLACE(s, '[^a-z0-9]', '', 'g');

  -- 4. Normalize Hindi consonant transliterations (chh/ch->c, kh->k, gh->g, th->t, dh->d, sh->s, w->v, d->r)
  s := REPLACE(REPLACE(s, 'chh', 'c'), 'ch', 'c');
  s := REPLACE(s, 'kh', 'k');
  s := REPLACE(s, 'gh', 'g');
  s := REPLACE(s, 'th', 't');
  s := REPLACE(s, 'dh', 'd');
  s := REPLACE(s, 'sh', 's');
  s := REPLACE(s, 'w', 'v');
  s := REPLACE(s, 'd', 'r'); -- Matches Pahad/Pahar, Bhaisod/Bhaisor, Bhudkuda/Bhurkura, Bairkhad/Bairkhar

  -- 5. Normalize vowel variations (ee->i, oo->u, aa->a, iya->ia, ue/ui->i, ai->e, au->o)
  s := REPLACE(REPLACE(REPLACE(s, 'ee', 'i'), 'oo', 'u'), 'aa', 'a');
  s := REPLACE(s, 'iya', 'ia');
  s := REPLACE(REPLACE(s, 'ue', 'i'), 'ui', 'i');
  s := REPLACE(REPLACE(s, 'ai', 'e'), 'au', 'o');

  -- 6. Normalize trailing nasal 'n' or silent 'h' after 'a' (Chhataha/Chhatahan, Bagaha/Bagahan, Bahuarah/Bahuara)
  s := REGEXP_REPLACE(s, 'a[nh]$', 'a');

  -- 7. Remove internal schwa 'a' vowels while preserving first and last character
  IF LENGTH(s) > 2 THEN
    s := SUBSTRING(s FROM 1 FOR 1)
         || REPLACE(SUBSTRING(s FROM 2 FOR LENGTH(s) - 2), 'a', '')
         || SUBSTRING(s FROM LENGTH(s) FOR 1);
  END IF;

  -- 8. Collapse consecutive duplicate letters (e.g. Bichchhi -> Bici)
  s := REGEXP_REPLACE(s, '(.)\1+', '\1', 'g');

  RETURN s;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_duplicate_post_office()
 RETURNS trigger
 LANGUAGE plpgsql
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_phonetic_addr TEXT;
  v_norm_office   TEXT;
  v_existing_id   BIGINT;
  v_existing_addr TEXT;
BEGIN
  NEW."Address" := TRIM(REGEXP_REPLACE(NEW."Address", '\s+', ' ', 'g'));
  NEW."Office"  := TRIM(REGEXP_REPLACE(NEW."Office", '\s+', ' ', 'g'));

  v_phonetic_addr := public.postal_phonetic_key(NEW."Address");
  v_norm_office   := LOWER(NEW."Office");

  SELECT id, "Address"
  INTO v_existing_id, v_existing_addr
  FROM public.post_offices
  WHERE is_deleted = false
    AND LOWER(TRIM(REGEXP_REPLACE("Office", '\s+', ' ', 'g'))) = v_norm_office
    AND public.postal_phonetic_key("Address") = v_phonetic_addr
  ORDER BY
    CASE WHEN REPLACE("Address", '.', '') ~* '\m(bo|so|ho)\M' THEN 0 ELSE 1 END,
    id ASC
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    -- If existing record is a plain village and the new record has BO/SO/HO, upgrade the existing record's name
    IF REPLACE(v_existing_addr, '.', '') !~* '\m(bo|so|ho)\M'
       AND REPLACE(NEW."Address", '.', '') ~* '\m(bo|so|ho)\M' THEN
      UPDATE public.post_offices
      SET "Address" = NEW."Address",
          "Pin"     = COALESCE(NEW."Pin", "Pin")
      WHERE id = v_existing_id;
    END IF;

    -- Skip inserting the duplicate row
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_request(req_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_request RECORD;
    v_is_admin BOOLEAN;
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();

    -- Verify admin status
    SELECT EXISTS (SELECT 1 FROM public.admins WHERE id = v_user_id) INTO v_is_admin;
    IF NOT v_is_admin THEN 
        RAISE EXCEPTION 'Only administrators can reject requests.'; 
    END IF;

    -- Get and lock the request row
    SELECT * INTO v_request FROM public.edit_requests WHERE id = req_id FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'Request not found.'; END IF;
    IF v_request.status != 'PENDING' THEN RAISE EXCEPTION 'Request is already %.', v_request.status; END IF;

    -- Update status and stamp who rejected it
    UPDATE public.edit_requests 
    SET status = 'REJECTED', 
        last_approved_by = v_user_id -- Reusing this column to track who finalized the action (rejection)
    WHERE id = req_id;

    RETURN 'REJECTED';
END;
$function$

CREATE OR REPLACE FUNCTION public.smart_capitalize(input_string text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    result TEXT := '';
    i INT;
    c TEXT;
    capitalize_next BOOLEAN := TRUE;
BEGIN
    IF input_string IS NULL THEN
        RETURN NULL;
    END IF;

    FOR i IN 1..length(input_string) LOOP
        c := substr(input_string, i, 1);

        -- If the character is a letter
        IF c ~ '[A-Za-z]' THEN
            IF capitalize_next THEN
                result := result || upper(c);
            ELSE
                result := result || c; -- Leave existing case alone
            END IF;
            capitalize_next := FALSE;

        -- If the character is a number, treat it as part of a word
        ELSIF c ~ '[0-9]' THEN
            result := result || c;
            capitalize_next := FALSE;

        -- If it's a space or punctuation, flag the next letter for capitalization
        ELSE
            result := result || c;
            capitalize_next := TRUE;
        END IF;
    END LOOP;

    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_approval(req_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_admin BOOLEAN;
    v_req RECORD;
    v_vote_count INT;
    v_new_po_id BIGINT;
    safe_pin INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.admins WHERE id = v_user_id
    ) INTO v_is_admin;

    SELECT * INTO v_req
    FROM public.edit_requests
    WHERE id = req_id AND status = 'PENDING'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Request not found or already resolved.';
    END IF;

    IF v_req.requested_by = v_user_id AND NOT v_is_admin THEN
        RAISE EXCEPTION 'You cannot vote on your own request.';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.request_approvals
        WHERE request_id = req_id AND approved_by = v_user_id
    ) THEN
        RAISE EXCEPTION 'You have already voted on this request.';
    END IF;

    INSERT INTO public.request_approvals (request_id, approved_by, is_admin)
    VALUES (req_id, v_user_id, v_is_admin);

    SELECT COUNT(*) INTO v_vote_count
    FROM public.request_approvals
    WHERE request_id = req_id;

    IF v_is_admin OR v_vote_count >= 5 THEN
        IF NULLIF(TRIM(COALESCE(v_req.proposed_data->>'Pin', '')), '') ~ '^\d+$' THEN
            safe_pin := TRIM(v_req.proposed_data->>'Pin')::INTEGER;
        ELSE
            safe_pin := NULL;
        END IF;

        IF v_req.action_type = 'ADD' THEN
            INSERT INTO public.post_offices (
                "Address", "Office", "Pin", user_id, last_modified_by, last_approved_by, upload_method, is_deleted
            ) VALUES (
                v_req.proposed_data->>'Address',
                v_req.proposed_data->>'Office',
                safe_pin,
                v_req.requested_by,
                v_req.requested_by,
                v_user_id,
                'manual',
                FALSE
            ) RETURNING id INTO v_new_po_id;

            UPDATE public.edit_requests
            SET status = 'APPROVED',
                post_office_id = v_new_po_id,
                last_approved_by = v_user_id
            WHERE id = req_id;

        ELSIF v_req.action_type = 'EDIT' THEN
            UPDATE public.post_offices
            SET "Address" = v_req.proposed_data->>'Address',
                "Office" = v_req.proposed_data->>'Office',
                "Pin" = safe_pin,
                last_modified_by = v_req.requested_by,
                last_approved_by = v_user_id
            WHERE id = v_req.post_office_id;

            UPDATE public.edit_requests
            SET status = 'APPROVED',
                last_approved_by = v_user_id
            WHERE id = req_id;

        ELSIF v_req.action_type = 'DELETE' THEN
            UPDATE public.post_offices
            SET is_deleted = TRUE,
                last_modified_by = v_req.requested_by,
                last_approved_by = v_user_id
            WHERE id = v_req.post_office_id;

            UPDATE public.edit_requests
            SET status = 'APPROVED',
                last_approved_by = v_user_id
            WHERE id = req_id;
        END IF;

        RETURN 'APPROVED';
    END IF;

    RETURN 'VOTED';
END;
$function$
